-- Sixty5 (BIM4) catalogs: roles + hourly rates, persons, suppliers + contracts, products + purchase prices. Generated by build_sixty5_plan.py. Idempotent.
-- Every id starts with bld- (persons / lines: uuid5). Needs start1 + start2 + start4.
DO $$ BEGIN IF to_regclass('public."personTable"') IS NULL OR to_regclass('public."productPriceTable"') IS NULL THEN RAISE EXCEPTION 'Run start1 + start2 + start4 first'; END IF; END $$;
BEGIN;

-- measureUnitTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

-- resourceRoleFolderTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

